ee:message.ee:set-payload:
%dw 2.0
output application/json

var backendStatus =
    vars.caseUpdateStatusCode default 500

var backendBody =
    vars.caseUpdateResponse default {}

---
{
    status: "failed",

    errorCode:
        backendBody.errorCode
        default (
            if (backendStatus == 400)
                "INVALID_CASE_UPDATE"
            else if (backendStatus == 404)
                "CASE_NOT_FOUND"
            else if (backendStatus == 405)
                "METHOD_NOT_ALLOWED"
            else if (backendStatus == 503)
                "SYSTEM_API_UNAVAILABLE"
            else
                "CASE_UPDATE_FAILED"
        ),

    message:
        backendBody.message
        default (
            if (backendStatus == 400)
                "The supplied case update values are invalid."
            else if (backendStatus == 404)
                "Support case with ID '" ++
                (vars.caseId default "") ++
                "' does not exist."
            else if (backendStatus == 405)
                "The requested case operation is not supported."
            else if (backendStatus == 503)
                "The case update service is temporarily unavailable."
            else
                "The support case could not be updated."
        ),

    errorDescription:
        backendBody.errorDescription
        default "The System API rejected the case update request.",

    correlationId:
        backendBody.correlationId
        default correlationId
}

%dw 2.0 output application/json
var backendBody = vars.caseUpdateResponse default {}
--- { status: "success",
message: backendBody.message default "Case updated successfully",
caseId: backendBody.caseId default backendBody.id default backendBody.data.caseId default backendBody.data.id default vars.caseId,
data: backendBody.data default { status: vars.inboundUpdatePayload.status, priority: vars.inboundUpdatePayload.priority } }

%dw 2.0 output application/json
var caseList = vars.caseHistoryResponse.data default vars.caseHistoryResponse.cases default []
--- { status: "success", customerId: vars.customerId, cases: caseList map (item) -> { caseId: item.caseId default item.id default "", subject: item.subject default "", description: item.description default "", priority: item.priority default "", status: item.status default "" } }

%dw 2.0 output application/json
var createdCaseId = vars.caseCreateResponse.id default vars.caseCreateResponse.caseId default vars.caseCreateResponse.data.id default vars.caseCreateResponse.data.caseId default ""
--- { status: "success", message: vars.caseCreateResponse.message default "Case created successfully", caseId: createdCaseId }
